presetParts.perFrame:
warp = 0;
counter1 = if(equal(counter2,1),if(equal(counter1,1),0,counter1+.02),1);
counter2 = if(equal(counter1,1),if(equal(counter2,1),0,counter2+.02),1);
cdelay1 = if(equal(cdelay2,1),1,if(equal(colorcounter%2,1),if(equal(counter1,1),2 ,0), if(equal(counter2,1),2,0)));
